import { Task } from "wasp/entities";
import { GetTasks } from "wasp/server/operations";

type GetTasksArgs = {
  overdueOnly?: boolean;
};

export const getTasks: GetTasks<GetTasksArgs, Task[]> = async (
  { overdueOnly },
  context
) => {
  const where = overdueOnly ? { dueDate: { lt: new Date() } } : {};

  return context.entities.Task.findMany({
    where,
    orderBy: { dueDate: "asc" },
  });
};

